        String id = sheetId == null ? "" : sheetId.trim();
        long cid;
        try {
            cid = Long.parseLong(claimId == null ? "" : claimId.trim());
        } catch (NumberFormatException e) {
            throw new BadRequestException("no such claim");
        }
        claim.set(ClaimStatusChange.apply(id, cid, action,
                request == null ? null : request.reason(), by, repository, periods, settings, audit, rollup));
    }
}
# Change a claim's status: open (DRAFT -> OPEN), settle (OPEN -> SETTLED, or PENDING when a clerk settles
# above the clerk limit), approve (PENDING -> SETTLED), reject with a reason (PENDING -> OPEN) or void
# (DRAFT, OPEN or PENDING -> VOID). Any other change is refused (400) and writes nothing.
change:
  class: net.officefloor.hq.app.claim.ChangeClaimStatus
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim

input.command:
python3 - <<'EOF'
p='src/main/frontend/features/claims/claims.slot.tsx'
s=open(p).read()
anchor='/** The sheet\'s claimed-total'
add='''/** Settle the selected claims together: the server settles, in list order and by the rules of a single
 *  settle, each that can be settled (one sent to PENDING counts) and leaves the rest; the bar shows how
 *  many were settled and how many refused (gone while it runs). */
function BulkSettle({ sheetId }: { sheetId: string }) {
  const selection = useClaimSelection(sheetId);
  const queryClient = useQueryClient();
  const submitOnce = useSingleFlight();
  const bulk = useMutation({
    mutationFn: (claimIds: number[]) =>
      postJson<{ settled: number; refused: number }>(`/api/sheets/${encodeURIComponent(sheetId)}/bulk-settle`, { claimIds }),
    onSuccess: () => selection.clear(),
    onSettled: async () => {
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
    },
  });
  return (
    <p data-testid="bulk-settle-bar">
      <button
        type="button"
        data-testid="bulk-settle"
        disabled={bulk.isPending}
        onClick={() =>
          submitOnce(() => {
            bulk.reset();
            return bulk.mutateAsync([...selection.ids]);
          })
        }
      >
        Settle selected ({selection.ids.size})
      </button>
      {bulk.isSuccess && (
        <>
          {' '}
          Settled <strong data-testid="bulk-settled">{bulk.data.settled}</strong>, refused{' '}
          <strong data-testid="bulk-settle-refused">{bulk.data.refused}</strong>
        </>
      )}
      {bulk.isError && <span data-testid="bulk-settle-error">{bulk.error.message}</span>}
    </p>
  );
}

'''
s=s.replace(anchor,add+anchor,1)
s=s.replace("  SheetBody.fill({ order: 15, Component: BulkOpen }),\n","  SheetBody.fill({ order: 15, Component: BulkOpen }),\n  SheetBody.fill({ order: 16, Component: BulkSettle }),\n")
open(p,'w').write(s)
EOF
